export CHECKPOINT_SKIP="commit before freeze, no data"; D=docs/reports/2026-11-06-degree-three-module-rss-rerun; git add $D .github/workflows/formal-module-rss.yml && git commit -q -m "formal: protocol, scripts and workflow for the degree-three module RSS rerun (draft, no data)

Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>
Claude-Session: https://claude.ai/code/session_01TCbLH96YZo1MqJwSbL3XNg" && python3 tools/experiment_protocol.py freeze $D/protocol.json --filed-before-affected-data 2>&1 | tail -3; python3 -c "import json;print(json.load(open('$D/protocol.json'))['freeze'])"; python3 tools/experiment_protocol.py validate $D/protocol.json | tail -1

export CHECKPOINT_SKIP="building export from collected CI data, no run"; D=docs/reports/2026-11-06-degree-three-module-rss-rerun; python3 -c "
import json;e=json.load(open('$D/export.json'))
for k in ('analysis','host','source','producer','files','flow','notes','backend'): print(k, json.dumps(e[k])[:300])
print(json.dumps(e['runs'][0])[:600])"; python3 -c "
